// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/characters/types.ts. Edit it there, then run `npm run sync:film`.
/*
 * Character system v2 — front-facing illustrated figures, viewBox 400×1000, feet at y≈955.
 * A Person (face, hair, skin, specs, build) never changes; an Outfit is swapped per event.
 */

export type Specs = "roundGold" | "rectDark" | "matteBlack" | "roundedSquare";
export type FaceShape = "male" | "female";
export type HairStyle = "groomNeat" | "silverSide" | "sidePart" | "quiff" | "kidMessy" | "centreBun";
export type Mouth = "smile" | "grin" | "softSmile";

export type Person = {
  id: string;
  name: string;
  /** Relationship label, exactly as provided — never invented. */
  role: string;
  face: FaceShape;
  skin: string;
  hair: HairStyle;
  hairColor: string;
  /** Greying at the temples. */
  greyTemples?: boolean;
  beard?: "short";
  specs?: Specs;
  mouth: Mouth;
  bindi?: boolean;
  /** Overall figure scale (1 = adult male). */
  scale: number;
  /** Head size relative to body — >1 reads younger. */
  headScale?: number;
};

export type SleeveKind = "full" | "elbow" | "short";

type Base = { sleeve: string; cuff: string; sleeveKind: SleeveKind; sleevePattern?: string };

export type Sherwani = Base & {
  kind: "sherwani";
  base: string;
  pattern: string;
  accent: string; // front-opening and hem panels
  bottom: string;
  shoes: "mojari";
  stole?: string;
  safa?: { color: string; stripe: string };
};
export type Bandhgala = Base & { kind: "bandhgala"; base: string; kurta: string; bottom: string; shoes: "formal"; pocketSquare: string };
export type Suit = Base & { kind: "suit"; base: string; shirt: string; tie: string; bottom: string; shoes: "formal" };
export type BlazerTee = Base & { kind: "blazerTee"; base: string; tee: string; bottom: string; shoes: "formal" };
export type CasualShirt = Base & { kind: "casualShirt"; base: string; bottom: string; shoes: "sneaker" };
export type Saree = Base & { kind: "saree"; base: string; border: string; blouse: string };
export type Lehenga = Base & {
  kind: "lehenga";
  base: string;
  blouse: string;
  border: string;
  drape: string; // dupatta across the body
  veil?: string; // sheer head dupatta
  bridal?: boolean;
};

export type Outfit = Sherwani | Bandhgala | Suit | BlazerTee | CasualShirt | Saree | Lehenga;

/** Joint rotations (degrees). L = viewer-left arm. Positive L / negative R = away from the body. */
export type Pose = {
  lShoulder: number;
  lElbow: number;
  rShoulder: number;
  rElbow: number;
  headTilt: number;
};

export const REST: Pose = { lShoulder: 7, lElbow: -6, rShoulder: -7, rElbow: 6, headTilt: 0 };

export type HeldProp = "laptop" | "diagram" | "console";
